import Taro from "@tarojs/taro";

/**
 * 当前页面是否显示title
 * 切记：每一个页面都要调用该方法，如果该页不需要显示title，传值为空即可，但是不能不调用，如果不调用，会自动显示其他页面的title或者tab，造成点击逻辑混乱
 * @param boolean  是否显示showTitle，必须为true，否则showtitle为全局变量，在页面是会显示之前的title
 * @param title    要显示的标题名称，如果不想显示的话赋值为空
 * @param level    一级页面为0，其他为1  注意：如果赋值为1，则显示title的地方会有 < 返回箭头
 * @param tab      该level属于哪个tab
 */
function isShowtitle(boolean = true, title = " ", level = 1, tab = 0) {
    // 测试show title
    if (boolean) {
        console.log('需要显示的title', `showtitle${boolean}${title}${level}${tab}`)
        if (window.la && window.la.showTitle) {
            window.la.showTitle({title: title, level: level, tab: tab});
        }
    }
}

export {isShowtitle};

/**
 * 当期页面是否显示tab  以及  在轻应用内隐藏底部tab icon
 * @param {*} boolean
 */
function isShowTab(boolean = true) {
    if (boolean) {
        console.log('设置tab====')
        let tabBean = [{
            tab: '智慧加油',
            url: '/pages/index1/index1'
        },
            {
                tab: '我的',
                url: '/pages/ucenter/ucenter'
            },
        ]
        if (window.la && window.la.showTab) {
            window.la.showTab({
                tabBean: tabBean
            });
        }
        console.log('process.env.TARO_ENV', process.env.TARO_ENV)

        if (process.env.TARO_ENV === 'h5') {
            hide()

            function hide() {
                Taro.hideTabBar().then(res => {
                    console.log('taro隐藏TabBar成功')
                }).catch(err => {
                    console.log(err, 'taro隐藏TabBar失败')
                })
                let ele = document.querySelector('.taro-tabbar__tabbar')
                console.log(ele,'ele')
                if (ele) {
                    ele.style.display = 'none'
                } else {
                    setTimeout(() => {
                        hide()
                    }, 0)
                }
            }
        }
    }
}

